//! What goes into the image: a list of absolute paths and their contents.
//!
//! Exactly **one directory level** is supported — `/bin/hello`, `/etc/motd` — and
//! that is asserted rather than assumed. Slices 5.7–5.9 need no deeper tree, and a
//! recursive builder would be code with no caller and no test that reflected a
//! real image. [`split_path`] is where the rule lives, so widening it later is one
//! function and its tests, not a search through the writer.

use crate::image::MkfsError;

/// One file in the image.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Entry {
    /// Absolute path, exactly `/<dir>/<name>`.
    pub path: String,
    /// File contents, verbatim.
    pub bytes: Vec<u8>,
}

/// The files to write, in the order they were added. Directories are implied by
/// the paths and created in first-seen order.
#[derive(Clone, Default, PartialEq, Eq, Debug)]
pub struct Manifest {
    pub entries: Vec<Entry>,
}

impl Manifest {
    /// An empty manifest.
    pub fn new() -> Self {
        Self::default()
    }

    /// Add a file. Paths are validated when the image is built, not here, so a
    /// caller assembling a manifest from argv reports every problem at once.
    pub fn add(&mut self, path: impl Into<String>, bytes: impl Into<Vec<u8>>) -> &mut Self {
        self.entries.push(Entry {
            path: path.into(),
            bytes: bytes.into(),
        });
        self
    }

    /// Total bytes of file content. Used by the block-budget precheck.
    pub fn total_bytes(&self) -> usize {
        self.entries.iter().map(|e| e.bytes.len()).sum()
    }
}

/// Split `/<dir>/<name>` into its two components.
///
/// Rejects anything else: a bare `/name`, a deeper `/a/b/c`, a relative path, a
/// trailing slash, an empty component, or a `.`/`..` component (which would
/// collide with the entries every directory already carries).
pub fn split_path(path: &str) -> Result<(&str, &str), MkfsError> {
    let bad = || MkfsError::BadPath(path.to_string());
    let rest = path.strip_prefix('/').ok_or_else(bad)?;
    let mut parts = rest.split('/');
    let dir = parts.next().ok_or_else(bad)?;

/// Width of the inline path field in an [`FS_LOOKUP`] payload.
///
/// The path is NUL-**padded** into it, so the longest path that can travel is
/// `FS_PATH_MAX - 1` bytes: a field with no NUL anywhere is `ENAMETOOLONG` rather
/// than a silently truncated path that could resolve to a different file. VFS
/// applies the same cap before building the request, so a client hears the errno
/// without a round trip.
pub const FS_PATH_MAX: usize = 64;

/// Largest byte count an FS server moves in one [`FS_READ`]. One block, the
/// staging buffer a server on a one-page stack can afford. A longer request is
/// **clamped** (a short read), not refused.
pub const FS_MAX_IO: usize = BDEV_BLOCK_SIZE;

// The FS range sits strictly above the VFS range and strictly below BDEV's (and
// therefore every other server request range) and the NOTIFY marker.
const _: () = assert!(FS_RQ_BASE > VFS_RQ_BASE + (NR_VFS_MSGS as i32 - 1));
const _: () = assert!(FS_RQ_BASE + (NR_FS_MSGS as i32 - 1) < BDEV_RQ_BASE);
--- VFS_OPEN payload ---
/// one at ~46 KB: no CI job installs the SDK, so the musl flavour is what
/// `qemu-smoke` actually builds and the only one this number may be tuned to.
/// `kernel/build.rs` asserts the built bytes fit and names this constant when
/// they do not, the `ROOTFS_IMAGE_BLOCKS` precedent.
///
/// Sits beside [`CDEV_MAX_IO`] / [`BDEV_MAX_IO`] / [`FS_MAX_IO`] as the fourth
/// transfer cap in this file, and is the only one that is not a staging chunk: a
/// short stage is useless, because an ELF cannot be loaded in pieces by a loader
/// that has no filesystem.
pub const VFS_EXEC_MAX: usize = 256 * 1024;

/// Offset of the caller's path-buffer address in a `VFS_OPEN` payload (u64, and
/// 8-aligned within the message for the reason [`VFS_BUF_OFF`] gives).
///
/// `VFS_OPEN` is a different message from `VFS_WRITE`, so sharing byte 0 with
/// [`VFS_FD_OFF`] is not an overlap — the FS band's `FS_SUPER_MINOR_OFF` /
/// `FS_SUPER_ROOT_OFF` pair does the same thing.
pub const VFS_PATH_OFF: usize = 0;
/// Offset of the path's length in a `VFS_OPEN` payload (i32).
pub const VFS_PATH_LEN_OFF: usize = 8;

// The VFS range sits strictly above the PM range and strictly below FS's (and
// therefore every other server request range) and the NOTIFY marker.
const _: () = assert!(VFS_RQ_BASE > PM_RQ_BASE + (NR_PM_MSGS as i32 - 1));
const _: () = assert!(VFS_RQ_BASE + (NR_VFS_MSGS as i32 - 1) < FS_RQ_BASE);
const _: () = assert!(VFS_RQ_BASE + (NR_VFS_MSGS as i32 - 1) < crate::ipc_const::NOTIFY_MESSAGE);

fn do_read(
    caller_e: Endpoint,
    msg: &Message,
    grants: &mut GrantPool<GRANT_SLOTS>,
    mfs: Endpoint,
) -> i32 {
    let req = rw::parse(msg);
    let proc_nr = endpoint_proc(caller_e).get();

    // The fd table's borrow ends here: `Fd` is `Copy`, so the destructuring `let`
    // leaves values behind and nothing is held across the SENDREC below. That is
    // the rule `fd.rs`'s module note states, and this is the call site it is
    // about.
    let (ino, pos) = match fd::resolve(proc_nr, req.fd) {
        Ok(Fd::File { ino, pos }) => (ino, pos),
        // There is no `CDEV_READ` until Phase 6 (RX needs `SYS_IRQCTL`), so a
        // console descriptor has nothing to read from. `ENOSYS` rather than
        // `EBADF`: the descriptor is perfectly good, the operation is what does
        // not exist yet.
        Ok(Fd::CharDev { .. }) => return ENOSYS,
        Ok(Fd::Unused) => return EBADF,
        Err(e) => return e,
    };

    let len = match rw::validate(req.len, req.buf) {
        Ok(len) => len,
        Err(e) => return e,
    };
    if len == 0 {
        // A legal empty read. No grant is issued, so a client polling with
        // `len = 0` cannot use it to probe the granting path.
        return 0;
    }

    let gid = match grants.grant_magic(mfs, caller_e, req.buf, len as u64, CPF_WRITE) {
        Ok(gid) => gid,
        Err(e) => return e,
    };
    let n = fs_read(mfs, ino as i32, gid, len as i32, pos);
    let _ = grants.revoke(gid);

    if n > 0 {
        // Only on real progress: advancing on an error or on EOF would silently
        // move the descriptor past bytes nobody read.
        fd::advance(proc_nr, req.fd, n as u64);
    }
    n
}

/// Serve one `VFS_EXEC_STAGE`. Returns the reply `m_type`: the staged byte count
/// (`> 0`), or a negative errno. On success the grant id is written to
/// [`VFS_EXEC_GRANT_OFF`] of the *cleared* reply payload.
///
/// This is VFS's half of exec-from-FS (slice 5.9, decision D6). PM asks for a
/// path; VFS reads the whole file into [`EXEC_STAGE`] and direct-grants it back,
/// so PM can name that grant in `SYS_EXEC` and the kernel can read the ELF
/// through it. **The bytes never pass through PM**, and the kernel gains no
/// filesystem — which is the whole point of doing it this way rather than
/// teaching `do_exec` to read a device.
///
/// The checks, in order — each is the first thing that can be wrong given the
/// ones before it:
///
/// 1. **The caller is PM.** Nothing else has any business asking VFS to stage an
///    image, and this is the one guard whose only exercise is a probe (init sends
///    the request directly, from `exec_denials`). PM never exits, so its boot
///    endpoint is stable — the same assumption RS already makes about `CLOCK`.
/// 2. The path parses ([`stage::parse_path`]): absolute, terminated, non-empty.
/// 3. Something is mounted (retried here, not cached — see [`ensure_mounted`]).
/// 4. The path resolves, and [`open::classify`] refuses a directory. A `read` on
///    one would answer `EISDIR` a step later; saying so here is the POSIX shape.
/// 5. The size fits ([`stage::stage_len`]).
///
/// Then the read loop, and then the grant. **The grantee is the kernel-stamped
/// `m_source`** — there is no payload field for it and there must never be one,
/// the rule every grant-issuing site in this tree follows.
